import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CoreFunction_functionFloor_TriageGen1Test {

    private CoreFunction coreFunction;
    private EvalContext mockContext;
    private Expression mockArg1;
    private Method functionFloorMethod;

    @Before
    public void setUp() throws Exception {
        mockContext = mock(EvalContext.class);
        mockArg1 = mock(Expression.class);

        // CoreFunction constructor requires functionCode and Expression array
        Expression[] args = new Expression[]{mockArg1};
        // Using a dummy function code (e.g., 1)
        coreFunction = new CoreFunction(1, args);

        // Since functionFloor is protected, we use reflection to access it for testing
        functionFloorMethod = CoreFunction.class.getDeclaredMethod("functionFloor", EvalContext.class);
        functionFloorMethod.setAccessible(true);
    }

    /**
     * Helper to invoke the protected method via reflection
     */
    private Object invokeFunctionFloor(EvalContext context) throws Exception {
        return functionFloorMethod.invoke(coreFunction, context);
    }

    @Test
    public void testFunctionFloor_PositiveDouble() throws Exception {
        when(mockArg1.computeValue(mockContext)).thenReturn(3.7);

        Object result = invokeFunctionFloor(mockContext);

        assertEquals(3.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_NegativeDouble() throws Exception {
        when(mockArg1.computeValue(mockContext)).thenReturn(-3.7);

        Object result = invokeFunctionFloor(mockContext);

        // Math.floor(-3.7) is -4.0
        assertEquals(-4.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_Integer() throws Exception {
        when(mockArg1.computeValue(mockContext)).thenReturn(5.0);

        Object result = invokeFunctionFloor(mockContext);

        assertEquals(5.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_Zero() throws Exception {
        when(mockArg1.computeValue(mockContext)).thenReturn(0.0);

        Object result = invokeFunctionFloor(mockContext);

        assertEquals(0.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_NegativeZero() throws Exception {
        when(mockArg1.computeValue(mockContext)).thenReturn(-0.0);

        Object result = invokeFunctionFloor(mockContext);

        assertEquals(-0.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_LargeValue() throws Exception {
        when(mockArg1.computeValue(mockContext)).thenReturn(Double.MAX_VALUE);

        Object result = invokeFunctionFloor(mockContext);

        assertEquals(Double.MAX_VALUE, (Double) result, 0.0);
    }

    @Test
    public void testFunctionFloor_SmallValue() throws Exception {
        when(mockArg1.computeValue(mockContext)).thenReturn(Double.MIN_VALUE);

        Object result = invokeFunctionFloor(mockContext);

        // Math.floor(Double.MIN_VALUE) is 0.0 because MIN_VALUE is the smallest positive constant
        assertEquals(0.0, (Double) result, 0.0);
    }

    @Test(expected = Exception.class)
    public void testFunctionFloor_WrongArgumentCount() throws Exception {
        // Create a function with 0 arguments to trigger assertArgCount(1) failure
        CoreFunction invalidFunction = new CoreFunction(1, new Expression[0]);
        Method method = CoreFunction.class.getDeclaredMethod("functionFloor", EvalContext.class);
        method.setAccessible(true);

        // This should throw an exception (likely AssertionError or similar depending on assertArgCount implementation)
        method.invoke(invalidFunction, mockContext);
    }

    @Test
    public void testFunctionFloor_WithInfoSetUtilMock() throws Exception {
        // This handles the case where InfoSetUtil.doubleValue might be called.
        // Since InfoSetUtil is a utility class, we mock the static call if possible, 
        // but here we rely on the fact that the input is already a Double to pass through.
        when(mockArg1.computeValue(mockContext)).thenReturn(10.9);

        Object result = invokeFunctionFloor(mockContext);

        assertEquals(10.0, (Double) result, 0.0001);
    }
}
